// @lc code=start
class Solution {
public:
    bool isPossible(vector<int>& v) {
        map<int, int> cnt;
        for (int i: v)
            cnt[i]++;
        map<int, int> need;
        for (int i: v)
            for (int j: v)
                for (int k: v){
                    if (i + j + k <= 1000 && cnt[j] && cnt[k]) {
                        cnt[j]-=2;
                        cnt[k]-=2;
                        need[i+k]++;
                        if (need[i+k] == 1)
                            return true;
                    }
                    cnt[j]++;
                    cnt[k]++;
                }
        // Lost, just return.
        return false;

    }
};
// @lc code=end

