```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

interface Measurable {
    double getArea();
}

class Circle implements Measurable {
    private double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    public double getArea() {
        return Math.PI * radius * radius;
    }
}

class Rectangle implements Measurable {
    private double length;
    private double width;

    public Rectangle(double length, double width) {
        this.length = length;
        this.width = width;
    }

    public double getArea() {
        return length * width;
    }
}

class Triangle implements Measurable {
    private double base;
    private double height;

    public Triangle(double base, double height) {
        this.base = base;
        this.height = height;
    }

    public double getArea() {
        return (base * height) / 2;
    }
}

public class MeasurableExample {

    public static void main(String[] args) {

        String fileName = "measurables.txt";
        double total = 0.0;
        int count = 0;

        try (BufferedReader br = new BufferedReader(new FileReader(fileName))) {

            String line;
            while ((line = br.readLine()) != null) {
                String[] parts = line.split(",");
                String type = parts[0].trim();
                String name = parts[1].trim();
                double price = Double.parseDouble(parts[2].trim());

                if (type.equals("circle")) {
                    total += new Circle(Double.parseDouble(name)).getArea() * price;
                    count++;
                } else if (type.equals("rectangle")) {
                    total += new Rectangle(Double.parseDouble(name), Double.parseDouble(parts[3].trim())).getArea() * price;
                    count++;
                } else if (type.equals("triangle")) {
                    total += new Triangle(Double.parseDouble(name), Double.parseDouble(parts[3].trim())).getArea() * price;
                    count++;
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        System.out.println("Total: " + total);
        System.out.println("Average: " + total / count);
    }
}
```
